import {View} from 'react-native';
import React, {FC} from 'react';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  runOnJS,
} from 'react-native-reanimated';
import {
  Gesture,
  GestureDetector,
  GestureHandlerRootView,
} from 'react-native-gesture-handler';
import styles from './styles';

type Props = {
  sliderWidth: number;
  min: number;
  max: number;
  step: number;
  defaultValue: number;
  onValueChange: (value: number) => void;
};

const SliderCM: FC<Props> = ({
  sliderWidth,
  min,
  max,
  step,
  onValueChange,
  defaultValue = 0,
}) => {
  const position = useSharedValue(defaultValue / (max / sliderWidth));
  const position2 = useSharedValue(sliderWidth);
  const opacity = useSharedValue(0);
  const zIndex = useSharedValue(0);
  const zIndex2 = useSharedValue(0);
  const context = useSharedValue(0);

  // Using new Gesture API
  const pan = Gesture.Pan()
    .onBegin(() => {
      context.value = position.value;
    })
    .onUpdate(e => {
      opacity.value = 0;
      if (context.value + e.translationX < 0) {
        position.value = 0;
      } else if (context.value + e.translationX > position2.value) {
        position.value = position2.value;
        zIndex.value = 1;
        zIndex2.value = 0;
      } else {
        position.value = context.value + e.translationX;
      }
    })
    .onEnd(() => {
      opacity.value = 1;
      runOnJS(onValueChange)(
        min +
          Math.floor(position.value / (sliderWidth / ((max - min) / step))) *
            step,
      );
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{translateX: position.value}],
    zIndex: zIndex.value,
  }));

  const sliderStyle = useAnimatedStyle(() => ({
    transform: [{translateX: position.value}],
    width: position2.value - position.value,
  }));

  return (
    <GestureHandlerRootView style={{width: sliderWidth}}>
      <View style={[styles.sliderContainer, {width: sliderWidth}]}>
        <View style={[styles.sliderBack, {width: sliderWidth}]} />
        <Animated.View style={[sliderStyle, styles.sliderFront]} />
        <GestureDetector gesture={pan}>
          <Animated.View style={[animatedStyle, styles.thumb]}></Animated.View>
        </GestureDetector>
      </View>
    </GestureHandlerRootView>
  );
};

export default SliderCM;
