import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import ItemDigitalCertificate from './components/ItemDigitalCertififcate';
import ModalAddCertificate from './components/ModalAddCertificate';
import styles from './styles';
import {useAppSelector} from '../../../hook/useRedux';
import HeaderCM from '../../../components/Header/HeaderCM';
import TextCM from '../../../components/Text';
import {IcBluePlus} from '../../../assets/images';
import {Agreement} from '../../../model/interface/general-setting.interface';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';

const DigitalCertificate = () => {
  const {t} = useTranslation();
  const [data, setData] = useState<Agreement[]>([]);
  const [showModal, setShowModal] = useState({
    addCertificate: false,
  });

  const GeneralSettingServices = useGeneralSettingServices();

  const {id} = useAppSelector(state => state.account.dataAccount);

  useEffect(() => {
    fetchListDigitalCertificate();
  }, []);

  const fetchListDigitalCertificate = () => {
    GeneralSettingServices.getListDigitalCertificate(id || 0)
      .then(res => {
        setData(res);
      })
      .catch(error => {
        console.log('error', error);
      });
  };

  const toggleModal = () => {
    setShowModal(prev => ({...prev, addCertificate: !prev.addCertificate}));
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.ST.DigitalCertificate.listDigitalCertificate')} />
      <View style={styles.mainContainer}>
        <View style={styles.titleContainer}>
          <TextCM style={styles.listDigitalCertificate}>
            {t('eContract.ST.DigitalCertificate.listDigitalCertificate')}
          </TextCM>
          <TouchableOpacity onPress={toggleModal} style={styles.row}>
            <IcBluePlus width={16} height={16} />
            <TextCM style={styles.regular}>
              {t('eContract.ST.DigitalCertificate.addNew')}
            </TextCM>
          </TouchableOpacity>
        </View>
        <ScrollView style={{flex: 1}}>
          <View style={styles.listCertificate}>
            {data.map(item => (
              <ItemDigitalCertificate
                key={item.id}
                data={item}
                fetching={fetchListDigitalCertificate}
              />
            ))}
          </View>
        </ScrollView>
      </View>
      {showModal.addCertificate && (
        <ModalAddCertificate
          isVisible={showModal.addCertificate}
          onClose={toggleModal}
          fetching={fetchListDigitalCertificate}
        />
      )}
    </SafeAreaView>
  );
};

export default DigitalCertificate;
