import {useNavigation, useRoute} from '@react-navigation/native';
import {debounce, isEmpty} from 'lodash';
import React, {useEffect, useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, RefreshControl, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {
  NavigationState,
  SceneRendererProps,
  TabBar,
  TabView,
} from 'react-native-tab-view';
import GroupRadio, {GroupData} from './components/GroupRadio';
import InputSearch from './components/InputSearch';
import ModalFilter from './components/ModalFilter';
import RelateDocumentItem from './components/RelateDocumentItem';
import {
  IRelatedDocument,
  RELATED_CHOOSE,
  getAclValue,
  getPathRelated,
} from './helper';
import styles from './styles';
import {useDispatch} from 'react-redux';
import TextCM from '../../../components/Text';
import HeaderCM from '../../../components/Header/HeaderCM';
import {IDocument} from '../../../model/interface/envelope.interface';
import {useDocumentStore} from '../../../navigation/SideMenu/store/app-store';
import {useAppSelector} from '../../../hook/useRedux';
import {
  useDocumentServices,
  useGeneralSettingServices,
} from '../../../hook/apiHook/useApi';
import Toast from 'react-native-toast-message';
import ButtonCM from '../../../components/Button';

const renderTabBar = (
  props: SceneRendererProps & {
    navigationState: NavigationState<{
      key: string;
      title: string;
    }>;
  },
) => (
  <TabBar
    {...props}
    indicatorStyle={styles.indicatorStyle}
    indicatorContainerStyle={styles.indicatorContainerStyle}
    style={styles.tabBarStyle}
    tabStyle={styles.tabStyle}
    activeColor="#0673C6"
    inactiveColor="#667085"
    contentContainerStyle={styles.contentContainerStyle}
    renderLabel={({route, focused, color}) => (
      <View
        style={{
          flex: 1,
          alignItems: 'center',
          justifyContent: 'center',
        }}>
        <TextCM style={(styles.txtTabText, {color})}>{route.title}</TextCM>
      </View>
    )}
  />
);

const DocumentRelate = () => {
  const route = useRoute<any>();
  const [index, setIndex] = React.useState(0);
  const {t} = useTranslation();

  const [groupUserBelong, setGroupUserBelong] = useState<any>([]);
  const {dataAccount} = useAppSelector(state => state.account);

  const GeneralSettingServices = useGeneralSettingServices();

  const [routes] = useState([
    {
      key: IRelatedDocument.myDocument,
      title: t('eContract.DC.DocumentRelate.myDocument'),
    },
    {
      key: IRelatedDocument.decentralizationGroup,
      title: t('eContract.DC.DocumentRelate.decentralizationGroup'),
    },
    {
      key: IRelatedDocument.decentralizationDirect,
      title: t('eContract.DC.DocumentRelate.decentralizationDirect'),
    },
  ]);

  const renderScene = ({route}: any) => {
    switch (route.key) {
      case IRelatedDocument.decentralizationGroup:
        return (
          <TabScreen
            tabKey={route.key}
            dataParams={groupUserBelong.map((item: any) => item.id)}
          />
        );
      case IRelatedDocument.decentralizationDirect:
        return (
          <TabScreen
            tabKey={route.key}
            dataParams={groupUserBelong.map((item: any) => item.id)}
          />
        );
      default:
        return <TabScreen tabKey={route.key} dataParams={undefined} />;
    }
  };

  useEffect(() => {
    getGroupsUserBelongto();
  }, []);

  const getGroupsUserBelongto = async () => {
    try {
      const params = {
        orgIn: dataAccount?.orgIn,
        idUser: dataAccount?.id,
        belong: true,
      };
      const resGroups = await GeneralSettingServices.getGroupsUserBelongto(
        params,
      );
      setGroupUserBelong(resGroups);
    } catch (error) {}
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.DC.DocumentRelate.label')} />
      <View style={{flex: 1}}>
        <TabView
          renderTabBar={renderTabBar}
          navigationState={{index, routes}}
          renderScene={renderScene}
          onIndexChange={setIndex}
        />
      </View>
    </SafeAreaView>
  );
};

const TabScreen = ({
  tabKey,
  dataParams,
}: {
  tabKey: IRelatedDocument;
  dataParams: any;
}) => {
  const {t} = useTranslation();
  const dispatch = useDispatch();
  const navigation = useNavigation();

  const refFlatList = useRef<any>();

  const [searchText, setSearchText] = useState('');
  const [isShowFilter, setIsShowFilter] = useState(false);
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [data, setData] = useState<IDocument[]>([]);
  const ItemTopRelatedDocument = useDocumentStore(
    state => state.itemTopRelatedDocument,
  );
  const ItemBottomRelatedDocument = useDocumentStore(
    state => state.itemBottomRelatedDocument,
  );

  const [currentChoose, setCurrentChoose] = useState<GroupData>(
    isEmpty(ItemTopRelatedDocument) ? RELATED_CHOOSE[0] : RELATED_CHOOSE[1],
  );

  const [totalPage, setTotalPage] = useState(1);
  const [page, setPage] = useState(0);

  const [isRefreshing, setIsRefreshing] = useState(false);

  const [filterData, setFilterData] = useState<any>({});

  const [currentSelected, setCurrentSelected] = useState<any[]>([]);

  const {
    currentFocused,
    setItemTopRelatedDocument,
    setItemBottomRelatedDocument,
  } = useDocumentStore();
  const {dataAccount} = useAppSelector(state => state.account);

  const DocumentServices = useDocumentServices();

  const toggleShowFilter = () => {
    setIsShowFilter(!isShowFilter);
  };

  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    getData(0, debouncedSearchText, filterData);
  }, [currentFocused, debouncedSearchText, filterData, dataParams]);

  const getData = async (
    page = 0,
    keyWord = '',
    filterData?: {sort: any; search: any; sort2?: string} | undefined,
  ) => {
    const pathApt = getPathRelated({
      type: currentFocused,
      tabKey: tabKey,
      owner: dataAccount.email,
    });
    const acl = getAclValue(tabKey, dataParams, dataAccount.email);
    const params = {
      page,
      size: 10,
      search: JSON.stringify({
        ...pathApt.params.search,
        keyWord,
        ...filterData?.search,
        acl: acl,
      }),
    };

    const data = await DocumentServices.getData(pathApt.path, params, {
      sort: filterData?.sort ? filterData.sort : pathApt.params.sort,
      sort2: 'name',
    });
    var newData = data.data;
    const updatedNew = newData.filter(
      (item1: any) =>
        !ItemBottomRelatedDocument?.some((item2: any) => item2.id === item1.id),
    );
    if (page) {
      const newDataFilter =
        !isEmpty(ItemTopRelatedDocument) && !isEmpty(ItemBottomRelatedDocument)
          ? updatedNew.filter(
              (item: any) => item.id !== ItemTopRelatedDocument.id,
            )
          : !isEmpty(ItemTopRelatedDocument)
          ? newData.filter((item: any) => item.id !== ItemTopRelatedDocument.id)
          : newData;
      setData(prev => [...prev, ...newDataFilter]);
    } else {
      const newDataFilter =
        !isEmpty(ItemTopRelatedDocument) && !isEmpty(ItemBottomRelatedDocument)
          ? updatedNew.filter(
              (item: any) => item.id !== ItemTopRelatedDocument.id,
            )
          : !isEmpty(ItemTopRelatedDocument)
          ? newData.filter((item: any) => item.id !== ItemTopRelatedDocument.id)
          : newData;
      setPage(0);
      setData(newDataFilter);
    }
    setTotalPage(data.totalPage);
    setIsRefreshing(false);
  };

  const onFilter = (data: any) => {
    setFilterData(data);
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    getData(0, debouncedSearchText, filterData);
  };

  const onEndReached = async () => {
    if (totalPage > 1 && page + 1 < totalPage) {
      getData(page + 1, debouncedSearchText, filterData);
      setPage(page + 1);
    }
  };

  const handleOnpressItem = (item: IDocument) => {
    if (currentChoose.id === 'top') {
      if (currentSelected.some(val => val.id === item.id)) {
        setCurrentSelected([]);
        return;
      } else {
        setCurrentSelected([item]);
      }
    } else {
      if (currentSelected.some(val => val.id === item.id)) {
        setCurrentSelected(prev => prev.filter(val => val.id !== item.id));
        return;
      } else {
        setCurrentSelected(prev => [...prev, item]);
      }
    }
  };

  const renderItem = ({item}: {item: IDocument}) => {
    return (
      <RelateDocumentItem
        data={item}
        tabKey={tabKey}
        onPressItem={handleOnpressItem}
        isSelected={currentSelected.some(val => val.id === item.id)}
      />
    );
  };

  const ToastMessage = () => {
    Toast.show({
      type: 'success',
      text1: t('eContract.DC.ChooseRelatedDocument'),
    });
    navigation.goBack();
  };
  const ToastMessageError = () => {
    Toast.show({
      type: 'error',
      text1: t('eContract.DC.SameDocumentationError'),
    });
  };

  const handleOnsubmit = async () => {
    try {
      let checkDocumentBottom = false;
      for (let i = 0; i < currentSelected.length; i++) {
        const res = await DocumentServices.getRelateDocument(
          currentSelected[i].id,
        );
        checkDocumentBottom = res.some((item: any) => item.level < 0);
        if (checkDocumentBottom) {
          break;
        }
      }
      if (checkDocumentBottom) {
        Toast.show({
          type: 'error',
          text1: t('eContract.DC.RelatedDocumentAlreadyExists'),
        });
        return;
      } else {
        if (
          currentChoose.id === 'top' &&
          ItemBottomRelatedDocument.some(
            val => val.id === currentSelected?.[0].id,
          )
        ) {
          ToastMessageError();
          return;
        }
        if (
          currentChoose.id === 'bottom' &&
          currentSelected.some(val => val.id === ItemTopRelatedDocument?.id)
        ) {
          ToastMessageError();
          return;
        }
        if (currentChoose.id === 'top') {
          setItemTopRelatedDocument(currentSelected?.[0]);
          ToastMessage();
        } else {
          setItemBottomRelatedDocument(currentSelected);
          ToastMessage();
        }
      }
    } catch (error) {}
  };

  return (
    <View style={styles.mainTabCtn}>
      <View style={{flex: 1}}>
        <InputSearch
          setSearchText={setSearchText}
          searchText={searchText}
          onPressFilter={toggleShowFilter}
        />
        <GroupRadio
          containerStyle={styles.radioCtn}
          data={RELATED_CHOOSE}
          currentValue={currentChoose}
          onPressData={item => {
            setCurrentChoose(item);
            setCurrentSelected([]);
          }}
          disable={!isEmpty(ItemTopRelatedDocument)}
        />
        <FlatList
          data={data}
          ref={refFlatList}
          keyExtractor={item => item.id}
          renderItem={renderItem}
          contentContainerStyle={styles.body}
          onEndReached={onEndReached}
          refreshControl={
            <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
          }
          ListEmptyComponent={<Nodata />}
          showsVerticalScrollIndicator={false}
        />
      </View>
      <ButtonCM
        disabled={currentSelected.length > 0 ? false : true}
        label={t('eContract.CM.BtnConfirm')}
        onPress={handleOnsubmit}
      />
      <ModalFilter
        onFilter={onFilter}
        isShowFilter={isShowFilter}
        toggleShowFilter={toggleShowFilter}
        filterData={filterData}
      />
    </View>
  );
};

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('eContract.DC.TxtNoData')}</TextCM>;
};

export default DocumentRelate;
