import _, {isEmpty} from 'lodash';
import {IConfigPassword} from '../../helper';
export const getObjectDiff = (obj1: any, obj2: any) => {
  if (isEmpty(obj1) || isEmpty(obj2)) return [];
  const diff = Object.keys(obj1).reduce((result, key) => {
    if (!obj2.hasOwnProperty(key)) {
      result.push(key);
    } else if (_.isEqual(obj1[key], obj2[key])) {
      const resultKeyIndex = result.indexOf(key);
      result.splice(resultKeyIndex, 1);
    }
    return result;
  }, Object.keys(obj2));

  return diff;
};

export const mappingTypeToLabel = (type: string, configType: string) => {
  if (configType === IConfigPassword.checkPasswordDuplicate) {
    return 'GS.passwordConfig.duplicatePasswordLabel';
  }
  if (configType === IConfigPassword.lockingAccountWrongPassword) {
    return 'GS.passwordConfig.lockAccountLabel';
  }
  switch (type) {
    case 'min-length':
      return 'GS.passwordConfig.minimumLengthTitle';
    case 'digit':
      return 'GS.passwordConfig.atleastDigit';
    case 'lowercase-char':
      return 'GS.passwordConfig.atleastLowercase';
    case 'uppercase-char':
      return 'GS.passwordConfig.atleastUppercase';
    case 'special-char':
      return 'GS.passwordConfig.atleastSpecialCharacter';
    case 'notifyAfterDay':
      return 'GS.passwordConfig.notifyAfterDayLabel';
    case 'resetAfterDay':
      return 'GS.passwordConfig.resetAfterDayLabel';
    case 'amount':
      return 'GS.passwordConfig.duplicatePasswordLabel';
    default:
      return '';
  }
};
