import {FC, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {isEmpty} from 'lodash';
import styles from './styles';
import {TouchableOpacity} from 'react-native';
import SearchComponent from '../search';
import RenderCreateTemplate from '../CreateSampleMessage';
import RenderTemplateMessage from '../ListSampleMessage';
import {
  ICreateTemplateMessage,
  INotification,
  ISearchResponse,
  StatusNotification,
} from '../../../../../model/interface/notification.interface';
import {ActionType} from '../../../../../model/enum/enum';
import {RegexUtils} from '../../../../../utils';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import {
  IcBluePlus,
  IconBlackDown,
  IconBlackSearch,
} from '../../../../../assets/images';
import BottomSheetCM from '../../../../../components/BottomSheet';
import Toast from 'react-native-toast-message';
import * as yup from 'yup';
import {yupResolver} from '@hookform/resolvers/yup';
import {Controller, useForm} from 'react-hook-form';
import React from 'react';
import {useCreateNotiServices} from '../../../../../hook/apiHook/useApi';
import TextFieldCM from '../../../../../components/TextField';

type Props = {
  data: INotification;
  actionTypeAuthorityOrForwardsProps: ActionType | undefined;
  onClose: () => void;
  onChangeData: (data: INotification) => void;
};

const BottomSheetAuthorityAndForward: FC<Props> = ({
  data,
  actionTypeAuthorityOrForwardsProps,
  onClose,
  onChangeData,
}) => {
  const {t} = useTranslation();
  const [stepAction, setStepAction] = useState<'chooseAccount' | 'writeReason'>(
    'chooseAccount',
  );
  const [isVisibleTemplateMessage, setIsVisibleTemplateMessage] =
    useState<boolean>(false);
  const [reasons, setReasons] = useState<string>('');
  const [userSelected, setUserSelected] = useState<ISearchResponse>({});
  const [isVisibleCreateTempalate, setIsVisibleCreateTempalate] =
    useState<boolean>(false);
  const [isVisibleSelectOrg, setIsVisibleSelectOrg] = useState<boolean>(false);

  const NotificationServices = useCreateNotiServices();

  const schema = yup
    .object({
      name: yup.string().required(t('eContract.SU.fieldRequired')),
      email: yup
        .string()
        .trim()
        .email(t('eContract.CM.EmailNotCorrectFormat'))
        .lowercase()
        .required(t('eContract.SU.fieldRequired')),
      phone: yup.string().required(t('eContract.SU.fieldRequired')),
    })
    .required();
  const {
    control,
    handleSubmit,
    setValue,
    getValues,
    watch,
    formState: {errors},
  } = useForm({
    mode: 'onBlur',
    defaultValues: {
      name: data?.recipients[0]?.name ?? '',
      phone: data?.recipients[0]?.phone ?? '',
      email: data?.recipients[0]?.email ?? '',
    },
    resolver: yupResolver(schema),
  });

  const handleSelectUser = (userSelect: ISearchResponse) => {
    setValue('email', userSelect?.email ?? '');
    setValue('name', userSelect?.personalName ?? '');
    setValue('phone', userSelect?.phone ?? '');
    handleCloseSelectUser();
  };

  const handleCloseSelectUser = () => {
    setIsVisibleSelectOrg(false);
  };

  const handleCloseCreateTemplate = async () => {
    setIsVisibleCreateTempalate(false);
  };

  const handleOpenCreateTemplate = async () => {
    setIsVisibleCreateTempalate(true);
  };

  const handleOnCloseSelectSamples = (item: ICreateTemplateMessage) => {
    setReasons(item.content);
    setIsVisibleTemplateMessage(false);
  };

  const handleSubmitAction = async () => {
    try {
      const envelopeId = data?.resourceId.substr(4);
      const recipientId = data?.recipients[0]?.id;
      const body = {
        envelopeId: envelopeId,
        recipientId: recipientId,
        name: userSelected?.personalName
          ? userSelected?.personalName
          : getValues('name'),
        email: userSelected?.email ? userSelected?.email : getValues('email'),
        phone: userSelected?.phone ? userSelected?.phone : getValues('phone'),
        reason: reasons,
        type: 'task',
        trace: '',
      };
      await NotificationServices.actionAuthorityOrForward(
        envelopeId,
        actionTypeAuthorityOrForwardsProps === ActionType.authority
          ? 'delegate'
          : 'forward',
        body,
      );
      Toast.show({
        type: 'success',
        text1:
          actionTypeAuthorityOrForwardsProps === ActionType.authority
            ? t('eContract.NT.message.successActionAuthority')
            : t('eContract.NT.message.successActionForward'),
      });
      const newNotification: INotification = {
        ...data,
        status:
          actionTypeAuthorityOrForwardsProps === ActionType.authority
            ? StatusNotification.delegated
            : StatusNotification.forwarded,
      };
      onChangeData(newNotification);
      onClose();
    } catch (error) {}
  };

  const getIsDisable = () => {
    if (!watch('name').trim().toLowerCase()) {
      return true;
    }

    if (!watch('email').trim().toLowerCase()) {
      return true;
    }
    if (!watch('phone').trim().toLowerCase()) {
      return true;
    }

    if (!RegexUtils.FORMAT_EMAIL.test(watch('email').trim().toLowerCase()))
      return true;

    if (
      !RegexUtils.REGEX_PHONE_NUMBER_9.test(watch('phone').trim().toLowerCase())
    )
      return true;

    const isDisabled =
      (data?.recipients[0].email.trim().toLowerCase() ===
        watch('email').trim().toLowerCase() &&
        data?.recipients[0]?.phone?.trim().toLowerCase() ===
          watch('phone').trim().toLowerCase() &&
        data?.recipients[0]?.name?.trim().toLowerCase() ===
          watch('name').trim().toLowerCase() &&
        isEmpty(userSelected)) ||
      (data?.recipients[0]?.email.trim().toLowerCase() ===
        userSelected?.email &&
        data?.recipients[0]?.phone?.trim().toLowerCase() ===
          userSelected?.phone &&
        data?.recipients[0]?.name?.trim().toLowerCase() ===
          userSelected?.personalName);
    return isDisabled;
  };

  return (
    <>
      {stepAction === 'chooseAccount' && (
        <>
          <Controller
            control={control}
            render={({field: {onChange, onBlur, value}}) => (
              <TextFieldCM
                label={t('eContract.NT.fillname')}
                isRequired
                onIconPress={() => setIsVisibleSelectOrg(true)}
                onBlur={onBlur}
                value={value}
                onChangeText={onChange}
                errorMessage={errors.name?.message}
                viewIconRight={<IconBlackSearch width={24} height={24} />}
              />
            )}
            name="name"
          />
          <Controller
            control={control}
            render={({field: {onChange, onBlur, value}}) => (
              <TextFieldCM
                label={t('eContract.NT.fillemail')}
                isRequired
                onBlur={onBlur}
                value={value}
                onChangeText={onChange}
                errorMessage={errors.email?.message}
              />
            )}
            name="email"
          />
          {!isEmpty(getValues('phone')) && (
            <Controller
              control={control}
              render={({field: {onChange, onBlur, value}}) => (
                <TextFieldCM
                  label={t('eContract.NT.fillPhone')}
                  isRequired
                  onBlur={onBlur}
                  value={value}
                  onChangeText={onChange}
                  errorMessage={errors.phone?.message}
                  isShowIconClear={false}
                />
              )}
              name="phone"
            />
          )}
          <ButtonCM
            disabled={getIsDisable()}
            style={{marginTop: 10}}
            label={t('eContract.CM.BtnConfirm')}
            onPress={() => setStepAction('writeReason')}
          />
        </>
      )}

      {stepAction === 'writeReason' && (
        <>
          <TextCM style={styles.text}>
            {t('eContract.NT.fillText', {email: getValues('email')})}
          </TextCM>

          <TouchableOpacity
            onPress={handleOpenCreateTemplate}
            style={styles.ctnAdd}>
            <IcBluePlus width={16} height={16} />
            <TextCM>{t('eContract.NT.createSampleMess')}</TextCM>
          </TouchableOpacity>

          <TextFieldCM
            multiline
            maxLength={100}
            label={
              actionTypeAuthorityOrForwardsProps === ActionType.authority
                ? t('eContract.NT.reasonAuthori')
                : t('eContract.NT.reasonForward')
            }
            isRequired
            value={reasons}
            onChangeText={setReasons}
            // styleIconRight={styles.styleIconRight}
            onIconPress={() => setIsVisibleTemplateMessage(true)}
            viewIconRight={<IconBlackDown width={16} height={16} />}
          />
          <ButtonCM
            disabled={isEmpty(reasons)}
            style={{marginTop: 10}}
            label={
              actionTypeAuthorityOrForwardsProps === ActionType.authority
                ? t('eContract.NT.TxtAuthority')
                : t('eContract.NT.TxtForward')
            }
            onPress={handleSubmitAction}
          />
        </>
      )}

      <BottomSheetCM
        title={t('eContract.NT.finduser')}
        isVisible={isVisibleSelectOrg}
        onClose={handleCloseSelectUser}
        renderContent={
          <SearchComponent
            onSave={handleSelectUser}
            onSelect={setUserSelected}
          />
        }
      />

      <BottomSheetCM
        title={t('eContract.NT.createSample')}
        isVisible={isVisibleCreateTempalate}
        onClose={handleCloseCreateTemplate}
        withKeyboardAvoidingView={true}
        renderContent={
          <RenderCreateTemplate onClose={handleCloseCreateTemplate} />
        }
      />

      <BottomSheetCM
        title={t('eContract.NT.reasonSample')}
        isVisible={isVisibleTemplateMessage}
        onClose={() => setIsVisibleTemplateMessage(false)}
        renderContent={
          <RenderTemplateMessage
            handleCloseTemplateMessage={handleOnCloseSelectSamples}
          />
        }
      />
    </>
  );
};

export default BottomSheetAuthorityAndForward;
