import {
  IconGreenReviewer,
  IconOrangeReviewer,
  IconRedReviewer,
  IconBlueReviewer,
  IconGreenSigner,
  IconOrangeSigner,
  IconRedSigner,
  IconBlueSigner,
  IconGreenStamper,
  IconOrangeStamper,
  IconRedStamper,
  IconBlueStamper,
  IconGreenCoordinator,
  IconOrangeCoordinator,
  IconRedCoordinator,
  IconBlueCoordinator,
  IconGreenCC,
  IconOrangeCC,
  IconRedCC,
  IconBlueCC,
} from '../../../../../../../assets/images';

export const getIconBlock = (data: any) => {
  switch (data.role) {
    case 'reviewer':
      switch (data.color) {
        case '#219342':
          return <IconGreenReviewer width={28} height={28} />;
        case '#E18308':
          return <IconOrangeReviewer width={28} height={28} />;
        case '#DA3E33':
          return <IconRedReviewer width={28} height={28} />;
        default:
          return <IconBlueReviewer width={28} height={28} />;
      }

    case 'signer':
      switch (data.color) {
        case '#219342':
          return <IconGreenSigner width={28} height={28} />;
        case '#E18308':
          return <IconOrangeSigner width={28} height={28} />;
        case '#DA3E33':
          return <IconRedSigner width={28} height={28} />;
        default:
          return <IconBlueSigner width={28} height={28} />;
      }
    case 'stamper':
      switch (data.color) {
        case '#219342':
          return <IconGreenStamper width={28} height={28} />;
        case '#E18308':
          return <IconOrangeStamper width={28} height={28} />;
        case '#DA3E33':
          return <IconRedStamper width={28} height={28} />;
        default:
          return <IconBlueStamper width={28} height={28} />;
      }
    case 'coordinator':
      switch (data.color) {
        case '#219342':
          return <IconGreenCoordinator width={28} height={28} />;
        case '#E18308':
          return <IconOrangeCoordinator width={28} height={28} />;
        case '#DA3E33':
          return <IconRedCoordinator width={28} height={28} />;
        default:
          return <IconBlueCoordinator width={28} height={28} />;
      }
    case 'cc':
      switch (data.color) {
        case '#219342':
          return <IconGreenCC width={28} height={28} />;
        case '#E18308':
          return <IconOrangeCC width={28} height={28} />;
        case '#DA3E33':
          return <IconRedCC width={28} height={28} />;
        default:
          return <IconBlueCC width={28} height={28} />;
      }
    default:
      break;
  }
};
